"""Conversion between currencies."""

from decimal import ROUND_HALF_UP, Decimal, localcontext

from fxquote.rates import RateError, RateTable

MINOR_UNITS = {"JPY": 0, "KRW": 0, "KWD": 3, "BHD": 3}


def _rate(table: RateTable, code: str) -> Decimal:
    try:
        return table.rates[code]
    except KeyError:
        raise RateError(f"currency not in rate table: {code}") from None


def _round_to_minor(amount: Decimal, code: str) -> Decimal:
    places = MINOR_UNITS.get(code, 2)
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, amount.adjusted() + places + 2)
        result = amount.quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP)
    if result.is_zero():
        result = abs(result)
    return result


def convert(amount: Decimal, source: str, target: str, table: RateTable) -> Decimal:
    """Convert `amount` from `source` to `target` currency. See README.md for the rules."""
    source_rate = _rate(table, source)
    target_rate = _rate(table, target)
    with localcontext() as ctx:
        ctx.prec = 50
        converted = amount * target_rate / source_rate
    return _round_to_minor(converted, target)


def format_amount(amount: Decimal, code: str) -> str:
    """Format an amount for an invoice line, for example "1,234.50 USD"."""
    places = MINOR_UNITS.get(code, 2)
    rounded = _round_to_minor(amount, code)
    return f"{rounded:,.{places}f} {code}"

"""Reference rates published by the treasury rate service."""

import json
import re
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from urllib.error import URLError
from urllib.parse import urlencode
from urllib.request import urlopen

RATES_URL = "https://fx.treasury.internal/v1/rates"

_CODE = re.compile(r"[A-Z]{3}")


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def _check_code(code: object) -> str:
    if not isinstance(code, str) or _CODE.fullmatch(code) is None:
        raise RateError(f"invalid currency code: {code!r}")
    return code


def _parse_rate(code: str, value: object) -> Decimal:
    if not isinstance(value, str):
        raise RateError(f"rate for {code} is not a decimal string")
    try:
        rate = Decimal(value)
    except InvalidOperation:
        raise RateError(f"rate for {code} is not a decimal: {value!r}") from None
    if not rate.is_finite() or rate <= 0:
        raise RateError(f"rate for {code} must be positive and finite: {value!r}")
    return rate


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        payload = json.loads(text)
    except (TypeError, ValueError) as exc:
        raise RateError(f"response is not valid JSON: {exc}") from None
    if not isinstance(payload, dict):
        raise RateError("response is not a JSON object")

    base = _check_code(payload.get("base"))
    as_of = payload.get("as_of")
    if not isinstance(as_of, str):
        raise RateError("as_of must be a string")
    listed = payload.get("rates")
    if not isinstance(listed, dict):
        raise RateError("rates must be an object")

    rates = {base: Decimal(1)}
    for code, value in listed.items():
        _check_code(code)
        if code == base:
            continue
        rates[code] = _parse_rate(code, value)
    return RateTable(base=base, as_of=as_of, rates=rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    _check_code(base)
    url = f"{RATES_URL}?{urlencode({'base': base})}"
    try:
        with urlopen(url, timeout=timeout) as response:
            status = response.getcode()
            if status != 200:
                raise RateError(f"rate service unavailable: HTTP {status}")
            body = response.read()
    except (URLError, OSError, ValueError) as exc:
        if isinstance(exc, RateError):
            raise
        raise RateError(f"rate service unavailable: {exc}") from None

    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise RateError(f"response is not valid UTF-8: {exc}") from None
    table = parse_rates(text)
    if table.base != base:
        raise RateError(f"rate service answered for {table.base}, expected {base}")
    return table
